import { HttpErrorResponse } from '@angular/common/http';
import { Component, OnInit } from '@angular/core';
import {  NgForm } from '@angular/forms';
import { Router } from '@angular/router';
import { disease } from '../../model/disease';
import { DiseaseService } from '../../services/disease.service';


@Component({
  selector: 'app-disease',
  templateUrl: './disease.component.html',
  styleUrls: ['./disease.component.scss']
})
export class DiseaseComponent implements OnInit {

  constructor(private DiseaseService: DiseaseService ,private router :Router) { }

  ngOnInit(): void {
    this.get_all();
  }

  diseases: disease[];
  content_disease: boolean;
  public get_all() {
    this.DiseaseService.get_all_disease().subscribe(
      data => {
        if (data.status == 200) {
          this.diseases = data.body;
          this.content_disease = true;
        }
        else if (data.status == 204) {
          this.content_disease= false;
        }
      }, 
      (error: HttpErrorResponse) => {
        if (error.status ==403) {
          localStorage.clear();
          this.DiseaseService.clear();
          this.router.navigateByUrl('/login');
        }
      }
    )
  }


  new_disease: disease;
  existe: boolean;
  n:boolean;
  add_disease(disease: NgForm) {
    this.new_disease = disease.value;
    this.DiseaseService.add(this.new_disease).subscribe(
      (response) => {
        if (response== "201") {
          this.existe=false;
          this.get_all();
          this.alert('Disease successfully added', 'primary');
          disease.resetForm();
          this.hide()
        }
        else if 
        (response == "200")
        { this.existe=true;}
      },
      (error: HttpErrorResponse) => {
        if (error) { if (error.status == 403) {
          localStorage.clear();
          this.DiseaseService.clear();
          this.router.navigateByUrl('/login');
        }}
      }
      )
  }

  hide() {
    let element: HTMLElement = document.getElementById('r') as HTMLElement;
    element.click();
  }

  cancel_add(disease: NgForm)
  {
    disease.resetForm();
    this.existe=false;

  }

  alertsDismiss: any = [];
  alert(msg: string, type: string) {
    this.alertsDismiss.push({
      type: type,
      msg: msg,
      timeout: 2500
    });
  }
  

  public delete(classid: any) {
    if (window.confirm('Are you sure')) {
      this.DiseaseService.delete(classid).subscribe(
        (response: string) => {
          this.get_all()
          this.alert('Disease successfully deleted', 'danger');

        }
      ,
        (error: HttpErrorResponse) => {
          if (error) { console.log(error.message); console.log(error.status) }
        })
    }
  }


  disease_update: disease;
  new_value = "";
  public update(disease: disease) {
    if (window.confirm('Are you sure')) {
      this.new_value = (<HTMLInputElement>document.getElementById("disease_update_classename")).value;
      disease.classname = this.new_value;
      this.DiseaseService.update(disease).subscribe(
        (response: string) => {
          this.get_all();
          this.alert('Disease successfully updated', 'warning');

        },
        (error: HttpErrorResponse) => {
          if (error) {
            console.log(error.message); console.log(error.status)
          }
        }
      )
    }
  }

  public set(disease: disease) {
    this.disease_update = disease;
   (<HTMLInputElement>document.getElementById("disease_update_classename")).value = disease.classname;

  }
 
}

